ee:message.ee:set-payload:
%dw 2.0
output application/json
var activeSerice = (payload filter upper($.Estado) != p("global.inactivo"))[0]
---
if(!isEmpty(activeSerice))
	do{
		var characteristic = (activeSerice.Caracteristica_Servicio filter $.Caracteristica == p("global.migrado"))[0].Valor
		---
		if (!isEmpty(characteristic))
		{
			code: "OK",
			description: "Successful",
			characteristic: characteristic
		}else
		{
			code: "OK",
			description: "Successful",
			characteristic: "true"
		}
	}
else
{
	"status": 404,
	"code": "FAIL",
	"messageServer": "Record not found in MDM_SERVICIO_ACTIVO",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}
